package model;
import java.time.*;
public class Appointment { private int appointmentId,patientId,doctorId; private String patientName,doctorName,reason,status; private LocalDate appointmentDate; private LocalTime appointmentTime; public int getAppointmentId(){return appointmentId;} public void setAppointmentId(int v){appointmentId=v;} public int getPatientId(){return patientId;} public void setPatientId(int v){patientId=v;} public int getDoctorId(){return doctorId;} public void setDoctorId(int v){doctorId=v;} public String getPatientName(){return patientName;} public void setPatientName(String v){patientName=v;} public String getDoctorName(){return doctorName;} public void setDoctorName(String v){doctorName=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDate getAppointmentDate(){return appointmentDate;} public void setAppointmentDate(LocalDate v){appointmentDate=v;} public LocalTime getAppointmentTime(){return appointmentTime;} public void setAppointmentTime(LocalTime v){appointmentTime=v;} }
